CREATE TABLE "metadata"."pools"(pool text PRIMARY KEY,creator text NOT NULL,token text UNIQUE NOT NULL);CREATE TABLE "metadata"."documents"(pool text PRIMARY KEY REFERENCES "metadata"."pools"(pool),revision numeric(78,0) NOT NULL DEFAULT 0,document jsonb NOT NULL DEFAULT '{}',asset_id text,moderation_revision numeric(78,0) NOT NULL DEFAULT 0,blocked boolean NOT NULL DEFAULT false);CREATE TABLE "metadata"."assets"(id text PRIMARY KEY,pool text NOT NULL REFERENCES "metadata"."pools"(pool),state text NOT NULL CHECK(state IN ('CREATED','UPLOADING','QUARANTINED','VALIDATING','APPROVED','REJECTED','DELETED')),hash text NOT NULL,size bigint NOT NULL CHECK(size BETWEEN 1 AND 6291456),object_key text NOT NULL,scanner_engine text NOT NULL,scanner_revision text NOT NULL,UNIQUE(pool,hash));CREATE TABLE "metadata"."operations"(operation text PRIMARY KEY,pool text NOT NULL,actor text NOT NULL,body_hash text NOT NULL,revision numeric(78,0) NOT NULL);CREATE TABLE "metadata"."outbox"(pool text NOT NULL,revision numeric(78,0) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(pool,revision));
CREATE TABLE "metadata"."v2_documents"(pool text PRIMARY KEY REFERENCES "metadata"."pools"(pool),revision numeric(78,0) NOT NULL DEFAULT 0,document jsonb NOT NULL DEFAULT '{"description":"","tags":[],"socials":[]}',asset_id text,updated_at timestamptz);CREATE TABLE "metadata"."v2_operations"(operation text PRIMARY KEY,pool text NOT NULL,actor text NOT NULL,body_hash text NOT NULL,revision numeric(78,0) NOT NULL,result jsonb NOT NULL);CREATE TABLE "metadata"."v2_nonces"(wallet text NOT NULL,nonce text NOT NULL,operation text NOT NULL,digest text NOT NULL,PRIMARY KEY(wallet,nonce));CREATE TABLE "metadata"."v2_outbox"(pool text NOT NULL,revision numeric(78,0) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(pool,revision));